export const SECTIONS: Section[] = [{"id": 1, "table": 1, "title": "Apertura", "scene": "studio", "start": 0, "voice": 5, "end": 32.55384615384615}, {"id": 2, "table": 2, "title": "Contexto e inicio", "scene": "studio", "start": 33.45384615384615, "voice": 33.45384615384615, "end": 126.56923076923077}, {"id": 3, "table": 3, "title": "Transición a móvil", "scene": "stinger", "start": 127.46923076923078, "voice": 130.46923076923076, "end": 136.58846153846153}, {"id": 4, "table": 4, "title": "Entrevistas y decisiones — Rashid, Alcalde y encargado de emergencias", "scene": "field", "start": 137.48846153846154, "voice": 137.48846153846154, "end": 240.91923076923075}, {"id": 5, "table": 4, "title": "Entrevistas y decisiones — Maximiliano, Jefe de bomberos", "scene": "field", "start": 242.71923076923076, "voice": 242.71923076923076, "end": 335.7307692307692}, {"id": 6, "table": 4, "title": "Entrevistas y decisiones — Nicolás, Encargado de salud", "scene": "field", "start": 337.53076923076924, "voice": 337.53076923076924, "end": 422.5}, {"id": 7, "table": 4, "title": "Entrevistas y decisiones — Rafael, Encargado de emergencias", "scene": "field", "start": 424.3, "voice": 424.3, "end": 506.926923076923}, {"id": 8, "table": 5, "title": "Transición a estudio", "scene": "stinger", "start": 507.826923076923, "voice": 510.826923076923, "end": 512.7153846153846}, {"id": 9, "table": 6, "title": "Síntesis y cierre", "scene": "studio", "start": 513.6153846153845, "voice": 513.6153846153845, "end": 567.9884615384615}];
export const SEGS: Seg[] = [{"spk": "valentino", "text": "Muy buenas tardes a toda la comunidad que nos sigue a esta hora en vivo.", "start": 5, "end": 10.77, "block": 1}, {"spk": "valentino", "text": "Son las 16:00 horas y estamos en cobertura urgente por la erupción del volcán Chaitén, en la Región de los Lagos, en una jornada marcada por ceniza, evacuaciones, riesgo de lahares,", "start": 11.12, "end": 23.04, "block": 1}, {"spk": "valentino", "text": "cortes de caminos y sectores aislados.", "start": 23.39, "end": 25.7, "block": 1}, {"spk": "valentino", "text": "Hoy revisamos cómo se distribuyeron los 100 créditos disponibles y qué decisiones se tomaron en terreno.", "start": 26.05, "end": 32.2, "block": 1}, {"spk": "valentino", "text": "A las 05:40, SERNAGEOMIN informó un aumento abrupto de la actividad sísmica del volcán y llamó a preparar evacuación y alejarse de cauces y zonas de peligro.", "start": 33.45, "end": 43.84, "block": 2}, {"spk": "valentino", "text": "A las 07:10 comenzó una emisión importante de ceniza: cambió el viento, la nube avanzó sobre sectores habitados, bajó la visibilidad y la ceniza se acumuló en calles y techumbres.", "start": 44.19, "end": 55.73, "block": 2}, {"spk": "valentino", "text": "A las 08:00 se ordenó la evacuación preventiva de sectores expuestos, aunque parte de la población demoró en salir por reunir documentos, medicamentos, pertenencias o mascotas.", "start": 56.08, "end": 66.08, "block": 2}, {"spk": "valentino", "text": "A las 09:20 la caída de ceniza afectó caminos, sistemas de agua y servicios básicos, dejando dos caminos secundarios inutilizados para vehículos chicos.", "start": 66.43, "end": 75.27, "block": 2}, {"spk": "valentino", "text": "A las 10:30 llegaron al centro de salud personas con dificultades respiratorias y se reportaron adultos mayores y personas con movilidad reducida sin desplazamiento autónomo.", "start": 75.62, "end": 85.24, "block": 2}, {"spk": "valentino", "text": "A las 11:40 vecinos avisaron de mascotas dentro de casas y familias que querían volver a buscarlas pese a la orden de evacuar.", "start": 85.59, "end": 94.43, "block": 2}, {"spk": "valentino", "text": "Al mediodía, a las 12:00, hubo una explosión mayor, alerta de lahares por cauces y quebradas, y una ruta principal quedó parcialmente bloqueada.", "start": 94.78, "end": 103.63, "block": 2}, {"spk": "valentino", "text": "A las 14:00 salud indicó que necesitaba mantener agua y electricidad para seguir operando, y bomberos recibió llamados para reingresar a zonas evacuadas.", "start": 103.98, "end": 112.83, "block": 2}, {"spk": "valentino", "text": "Finalmente, a las 16:00, el albergue empezó a quedarse sin capacidad suficiente, mientras persistían personas aisladas", "start": 113.18, "end": 119.33, "block": 2}, {"spk": "valentino", "text": "—incluida una familia aislada en un sector rural—, mascotas en viviendas y una ruta crítica sin despejar.", "start": 119.68, "end": 126.22, "block": 2}, {"spk": "valentino", "text": "Transición en vivo hacia los despachos y entrevistas con los voceros del comité en terreno.", "start": 130.47, "end": 136.24, "block": 3}, {"spk": "valentino", "text": "Estamos en vivo con Rashid, alcalde y encargado de emergencias.", "start": 137.49, "end": 141.33, "block": 4}, {"spk": "valentino", "text": "Alcalde, ¿por qué decidieron evacuar determinados sectores y no otros, qué criterios usaron para priorizar, y por qué se eligió evacuar un sector residencial, habilitar punto de encuentro,", "start": 141.68, "end": 152.45, "block": 4}, {"spk": "valentino", "text": "comunicar alerta a la población y trasladar población vulnerable, sin decidir apoyar la evacuación de personas con movilidad reducida ni rescatar mascotas y animales domésticos?", "start": 152.8, "end": 162.42, "block": 4}, {"spk": "rashid", "text": "Gracias, Valentino.", "start": 162.77, "end": 163.54, "block": 4}, {"spk": "rashid", "text": "Priorizamos según la exposición directa a la amenaza volcánica y la geografía del territorio:", "start": 163.89, "end": 169.27, "block": 4}, {"spk": "rashid", "text": "primero la sismicidad de las 05:40, luego la nube de ceniza y baja visibilidad desde las 07:10 y, a las 12:00, la explosión mayor con riesgo de lahares en cauces y quebradas.", "start": 169.62, "end": 181.93, "block": 4}, {"spk": "rashid", "text": "Decidimos comunicar alerta a la población para entregar instrucciones claras y advertir zonas peligrosas, y evacuar un sector residencial hacia una zona segura.", "start": 182.28, "end": 191.13, "block": 4}, {"spk": "rashid", "text": "Sumamos habilitar punto de encuentro para reunir y contabilizar a quienes evacuaban, y trasladar población vulnerable para sacar rápido a quienes estaban más expuestos en sectores de riesgo.", "start": 191.48, "end": 202.25, "block": 4}, {"spk": "valentino", "text": "¿Y por qué no se decidió apoyar la evacuación de personas con movilidad reducida ni rescatar mascotas y animales domésticos, considerando los avisos de las 08:00, 10:30 y 11:40?", "start": 202.6, "end": 213.75, "block": 4}, {"spk": "rashid", "text": "No se decidió rescatar mascotas y animales domésticos porque con ceniza, explosión mayor desde las 12:00, riesgo de lahares y gente queriendo reingresar a zonas evacuadas a las 14:00,", "start": 214.1, "end": 225.25, "block": 4}, {"spk": "rashid", "text": "enviar personal a buscar animales suponía exponer equipos innecesariamente.", "start": 225.6, "end": 229.07, "block": 4}, {"spk": "rashid", "text": "En cuanto a apoyar la evacuación de personas con movilidad reducida, optamos por concentrar ese esfuerzo dentro de trasladar población vulnerable para no restar créditos a otras medidas críticas.", "start": 229.42, "end": 240.57, "block": 4}, {"spk": "valentino", "text": "Pasamos con Maximiliano, jefe de bomberos.", "start": 242.72, "end": 245.03, "block": 5}, {"spk": "valentino", "text": "¿Por qué concentraron sus recursos en determinados lugares, qué rescates tuvieron que priorizar, y por qué se decidió desplegar bomberos en zona crítica,", "start": 245.38, "end": 254.22, "block": 5}, {"spk": "valentino", "text": "pero no se decidió rescatar personas aisladas ni rescatar mascotas y animales domésticos?", "start": 254.57, "end": 259.57, "block": 5}, {"spk": "maximiliano", "text": "Hola, Valentino, buenas tardes a todos.", "start": 259.92, "end": 262.23, "block": 5}, {"spk": "maximiliano", "text": "Concentramos fuerzas en la zona crítica por la baja visibilidad y acumulación de ceniza desde las 07:10, la explosión y posible descenso de lahares por cauces y quebradas desde las 12:00,", "start": 262.58, "end": 274.5, "block": 5}, {"spk": "maximiliano", "text": "y los llamados de personas que querían reingresar a zonas evacuadas a las 14:00.", "start": 274.85, "end": 280.24, "block": 5}, {"spk": "maximiliano", "text": "Desplegar bomberos en zona crítica permitió enfocar rescate, protección y control en un área prioritaria.", "start": 280.59, "end": 286.36, "block": 5}, {"spk": "valentino", "text": "¿Y qué explica que no se decidiera rescatar personas aisladas —pese a haber personas aisladas y una familia aislada en un sector rural— ni rescatar mascotas y animales domésticos?", "start": 286.71, "end": 297.86, "block": 5}, {"spk": "maximiliano", "text": "No se decidió rescatar personas aisladas porque llegar a puntos aislados requería equipos y transporte en medio de caminos afectados por ceniza desde las 09:20,", "start": 298.21, "end": 307.83, "block": 5}, {"spk": "maximiliano", "text": "dos caminos secundarios inutilizados para vehículos chicos, una ruta principal bloqueada al mediodía y una ruta crítica aún sin despejar a las 16:00,", "start": 308.18, "end": 317.02, "block": 5}, {"spk": "maximiliano", "text": "lo que exponía a nuestros equipos a quedar atrapados.", "start": 317.37, "end": 320.83, "block": 5}, {"spk": "maximiliano", "text": "Y no se decidió rescatar mascotas y animales domésticos porque la medida solo aplica si las condiciones permiten hacerlo sin exponer innecesariamente al personal, algo que no se daba con explosión,", "start": 321.18, "end": 333.11, "block": 5}, {"spk": "maximiliano", "text": "ceniza y reingresos no autorizados.", "start": 333.46, "end": 335.38, "block": 5}, {"spk": "valentino", "text": "Conversamos con Nicolás, encargado de salud.", "start": 337.53, "end": 339.84, "block": 6}, {"spk": "valentino", "text": "¿Qué ocurre si perdemos agua, electricidad o acceso, qué población debía recibir atención prioritaria, y por qué se eligió restablecer agua potable y desplegar personal de salud,", "start": 340.19, "end": 350.57, "block": 6}, {"spk": "valentino", "text": "sin decidir proteger el hospital o CESFAM ni restablecer la electricidad?", "start": 350.92, "end": 355.15, "block": 6}, {"spk": "nicolas", "text": "Gracias, Valentino.", "start": 355.5, "end": 356.27, "block": 6}, {"spk": "nicolas", "text": "Si perdemos agua, se comprometen la higiene, la descontaminación y la operación básica del recinto; si perdemos electricidad, fallan equipos, iluminación y respaldo;", "start": 356.62, "end": 365.47, "block": 6}, {"spk": "nicolas", "text": "y si perdemos acceso, no llegan pacientes ni insumos.", "start": 365.82, "end": 369.28, "block": 6}, {"spk": "nicolas", "text": "La población prioritaria son quienes presentan cuadros agudos —como dificultades respiratorias por ceniza desde las 10:30— y los grupos vulnerables o dependientes.", "start": 369.63, "end": 378.09, "block": 6}, {"spk": "nicolas", "text": "Por eso se decidió desplegar personal de salud para ampliar la atención en terreno y restablecer agua potable para sostener el agua de la población y los servicios esenciales,", "start": 378.44, "end": 389.6, "block": 6}, {"spk": "nicolas", "text": "tanto tras la afectación de las 09:20 como ante el aviso de las 14:00 y la actualización.", "start": 389.95, "end": 396.48, "block": 6}, {"spk": "valentino", "text": "¿Y por qué no se decidió proteger el hospital o CESFAM ni restablecer la electricidad, aun cuando a las 14:00 se advirtió la necesidad de mantener agua y electricidad?", "start": 396.83, "end": 407.99, "block": 6}, {"spk": "nicolas", "text": "Porque con un presupuesto acotado priorizamos restablecer agua potable y desplegar personal de salud como base sanitaria inmediata,", "start": 408.34, "end": 415.26, "block": 6}, {"spk": "nicolas", "text": "sin destinar otros 35 créditos conjuntos a proteger el hospital o CESFAM ni a restablecer la electricidad.", "start": 415.61, "end": 422.15, "block": 6}, {"spk": "valentino", "text": "Cerramos con Rafael, encargado de emergencias.", "start": 424.3, "end": 426.61, "block": 7}, {"spk": "valentino", "text": "Con los 100 de 100 créditos utilizados y 0 créditos restantes, ¿cómo distribuyeron los recursos disponibles, qué necesidad tuvieron que postergar, y por qué no se decidió habilitar un albergue,", "start": 426.96, "end": 438.5, "block": 7}, {"spk": "valentino", "text": "restablecer el camino principal ni proteger infraestructura crítica?", "start": 438.85, "end": 441.92, "block": 7}, {"spk": "rafael", "text": "Buenas tardes, Valentino.", "start": 442.27, "end": 443.43, "block": 7}, {"spk": "rafael", "text": "Los 100 créditos se distribuyeron en evacuar un sector residencial, desplegar bomberos en zona crítica, restablecer agua potable, desplegar personal de salud, habilitar punto de encuentro,", "start": 443.78, "end": 453.78, "block": 7}, {"spk": "rafael", "text": "comunicar alerta a la población y trasladar población vulnerable.", "start": 454.13, "end": 457.59, "block": 7}, {"spk": "rafael", "text": "Tuvimos que postergar la conectividad vial y la ampliación de refugio formal, sabiendo que a las 16:00 el albergue comenzaba a quedar sin capacidad suficiente,", "start": 457.94, "end": 467.55, "block": 7}, {"spk": "rafael", "text": "había personas aisladas y una ruta crítica seguía sin despejar.", "start": 467.9, "end": 471.75, "block": 7}, {"spk": "valentino", "text": "¿Por qué no se decidió habilitar un albergue, restablecer el camino principal ni proteger infraestructura crítica?", "start": 472.1, "end": 478.25, "block": 7}, {"spk": "rafael", "text": "Porque el límite era de 100 créditos.", "start": 478.6, "end": 481.3, "block": 7}, {"spk": "rafael", "text": "No se decidió habilitar un albergue para priorizar alerta, evacuación, punto de encuentro, agua y salud;", "start": 481.65, "end": 487.8, "block": 7}, {"spk": "rafael", "text": "no se decidió restablecer el camino principal porque movilizar maquinaria y personal en una vía crítica resultaba altamente complejo con ceniza, la explosión de las 12:00 y riesgo de lahares;", "start": 488.15, "end": 499.69, "block": 7}, {"spk": "rafael", "text": "y no se decidió proteger infraestructura crítica porque esos créditos ya estaban asignados a las prioridades seleccionadas.", "start": 500.04, "end": 506.58, "block": 7}, {"spk": "valentino", "text": "Regreso al estudio central.", "start": 510.83, "end": 512.37, "block": 8}, {"spk": "valentino", "text": "En síntesis, la erupción del volcán Chaitén obligó a este comité a usar los 100 créditos en alerta, evacuación, punto de encuentro, traslado de población vulnerable,", "start": 513.62, "end": 523.62, "block": 9}, {"spk": "valentino", "text": "despliegue de bomberos en zona crítica, despliegue de salud y agua potable.", "start": 523.97, "end": 528.58, "block": 9}, {"spk": "valentino", "text": "Quedaron fuera por presupuesto y condiciones de riesgo medidas como habilitar un albergue, rescatar personas aisladas, proteger el hospital o CESFAM, restablecer camino principal,", "start": 528.93, "end": 538.16, "block": 9}, {"spk": "valentino", "text": "restablecer electricidad, apoyar la evacuación de personas con movilidad reducida, proteger infraestructura crítica y rescatar mascotas y animales domésticos,", "start": 538.51, "end": 545.82, "block": 9}, {"spk": "valentino", "text": "dejando desafíos abiertos a las 16:00 en cupo de albergue, personas aisladas, ruta crítica y agua para salud.", "start": 546.17, "end": 553.09, "block": 9}, {"spk": "valentino", "text": "Es clave la responsabilidad gubernamental para coordinar recursos y despejar riesgos, y la responsabilidad civil de respetar alertas, evacuar a tiempo y no reingresar a zonas peligrosas.", "start": 553.44, "end": 563.83, "block": 9}, {"spk": "valentino", "text": "Muchas gracias por acompañarnos en esta transmisión en vivo.", "start": 564.18, "end": 567.64, "block": 9}];
